mapper.select:
SELECT
ROW_NUMBER() OVER() AS no,
menu_cd,
menu_nm_kr,
menu_nm_en,
menu_nm_mn,
menu_no,
menu_lvl,
top_menu_cd,
prgm_url,
menu_icon,
url,
use_yn,
(SELECT cd_nm
   FROM SYS_CD
  WHERE grp_id = 'use_yn'
    AND CONVERT(cd_id USING utf8mb4) COLLATE utf8mb4_unicode_ci
      = CONVERT(SYS_MENU.use_yn USING utf8mb4) COLLATE utf8mb4_unicode_ci) as use_yn_name,
menu_unq_no AS menu_seq,
sys_crt_usr_id,
sys_mdfr_id AS sys_upd_usr_id,
DATE_FORMAT(sys_mdfcn_dt,'%Y-%m-%d %H:%i:%S') AS sys_upd_dt,
DATE_FORMAT(sys_gen_dt,'%Y-%m-%d %H:%i:%S') AS sys_crt_dt
FROM SYS_MENU

    1=1
    AND menu_cd = #{menu_cd}
    AND menu_nm_kr = #{menu_nm_kr}
    AND menu_nm_en = #{menu_nm_en}
    AND menu_nm_mn = #{menu_nm_mn}
    AND menu_no = #{menu_no}
    AND menu_lvl = #{menu_lvl}
    AND top_menu_cd = #{top_menu_cd}
    AND prgm_url = #{prgm_url}
    AND url = #{url}
    AND use_yn = #{use_yn}
    AND sys_crt_usr_id = #{sys_crt_usr_id}
    AND sys_mdfr_id = #{sys_upd_usr_id}

